de(extensions.digest(pg_catalog.convert_to((component-'document_identity')::text,'UTF8'),'sha256'),'hex') THEN\n  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation lunch identity changed';END IF;\n IF p_feasibility#>'{initialBaseline,lunchDocument}' IS DISTINCT FROM component THEN\n  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='manual activation initial lunch identity changed';END IF;\n component:=NULL;\n metadata:=(p_feasibility->'initialBaseline')-ARRAY['document','projection','lunchDocument'];\n p_feasibility:=NULL;\n RETURN pg_catalog.encode(extensions.digest(pg_catalog.convert_to((jsonb_build_object('sourceId',p_source,'templateId',p_template,'managerId',p_manager,\n  'transitionDigest',p_transition->>'transitionDigest','feasibilityDigest',feasibility_identity,\n  'documentIdentity',document_identity,'projectionIdentity',projection_identity,'lunchIdentity',lunch_identity,'initialMetadata',metadata))::text,'UTF8'),'sha256'),'hex');\nEND $function$\n","replacement_sha256":"229fa0fb9f3ed58b848288ff285aa180a9609a9707a85352b6171b56cd89c3b5","metadata":{"owner":"postgres","acl":"{postgres=X/postgres}","definer":false,"volatility":"v","strict":false,"config":["search_path=pg_catalog, public"],"parallel":"u","language":"plpgsql"},"inventory":[]},{"identity":"public.static_weekly_read_approved_initial_basis(uuid,uuid,date,bigint,text)","preimage_sha256":"10147891ce95971e8a6b9a7eecf4f9d9470c1ec5470c6a123de5e093692bf484","replacement":"CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_initial_basis(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_template_id text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\ndeclare baseline public.static_weekly_approved_initial_baselines%rowtype;entry public.static_weekly_approved_template_catalog%rowtype;\n source jsonb;revision bigint;templates jsonb;bindings jsonb;\nbegin\n perform public.static_weekly_v3_assert_cont