where availability->'restrictions' ? (r->>'locationId'))\n    or (item->>'owner_slot_id'=basis#>>'{ownerConfig,slots,TAMMY,slotId}' and w->>'locationCodeSnapshot' not in('TETON','NORTH_WEST_PASSAGE','EAST_END_RESTROOMS','CHINA'))\n   then raise exception 'Manual native physical members, hard eligibility or scoped restriction changed: work %, fields %',item->>'work_id',\n    (select coalesce(jsonb_agg(k order by k),'[]') from (select jsonb_object_keys(w||expected) k) q where w->k is distinct from expected->k);end if;\n   if not day_changed and (link is not null or item->'owner_slot_id' is distinct from parent->'ownerSlotId' or w->'window' is distinct from parent->'window'\n    or w->'serviceEffortMinutes' is distinct from parent->'serviceEffortMinutes' or w->'serviceEffortProvenance' is distinct from parent->'serviceEffortProvenance')\n   then raise exception 'Manual native changed an approved normal day';end if;\n   if day_changed and (window_end>parent#>>'{window,end}' or window_start<case\n    when parent#>>'{window,start}'<=normal_start and parent#>>'{window,end}'>normal_start\n     then least(parent#>>'{window,start}',complete_start) else parent#>>'{window,start}' end)\n   then raise exception 'Manual native custody exceeds its exact parent boundary';end if;\n   -- A single unchanged owner can continue across the complete-crew arrival.\n   -- That harmless merged row must still preserve the whole early base prefix.\n   if day_changed and window_start<complete_start and (item->'owner_slot_id' is distinct from parent->'ownerSlotId'\n    or window_start<>parent#>>'{window,start}' or window_end<least(parent#>>'{window,end}',complete_start))\n   then raise exception 'Manual native early own-base custody differs';end if;\n   if day_changed and window_end>complete_start then\n    if window_end>complete_end then raise exception 'Manual native actual full-site window differs';end if;\n    for phase in select value from jsonb_array_elements(plan->'phaseOwners') where value#>>'{window,start}'<window_end and window_start<value#>>'{window,end}' loop\n     if phase#>>array['owners',w->>'locationCodeSnapshot'] is distinct from item->>'owner_slot_id' then raise exception 'Manual native selected phase differs from stored custody';end if;\n    end loop;\n   end if;\n   select assignment_id into strict assignment from public.weekly_schedule_slot_assignments\n    where version_id=version and day_of_week=dow and work_id=parent->>'workId';\n   links:=links||jsonb_build_object(item->>'plan_work_id',assignment::text);\n  end loop;\n\n  -- Every physical group tiles the complete actual staffed window once.\n  for code in select r->>'code' from jsonb_array_elements(policy->'groups') r loop\n   previous_end:=complete_start;previous_owner:=null;\n   for item in select r from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text\n    and r#>>'{work_snapshot,locationCodeSnapshot}'=code and r#>>'{work_snapshot,window,end}'>complete_start\n    order by r#>>'{work_snapshot,window,start}' loop\n    window_start:=greatest(complete_start,item#>>'{work_snapshot,window,start}');window_end:=least(complete_end,item#>>'{work_snapshot,window,end}');\n    if window_end<=window_start then continue;end if;\n    if window_start<>previous_end then raise exception 'Manual native full-site gap or overlap';end if;\n    if day_changed and previous_owner is not null and previous_owner<>item->>'owner_slot_id' and not exists(\n     select 1 from jsonb_array_elements(expected_availability) r where r->>'serviceDate'=day::text and r->>'slotId'=previous_owner and r#>>'{shift,end}'=window_start)\n    then raise exception 'Manual native owner moved before the static departure';end if;\n    previous_end:=window_end;previous_owner:=item->>'owner_slot_id';\n   end loop;\n   if previous_end<>complete_end then raise exception 'Manual native full-site coverage incomplete';end if;\n   select sum((r->>'serviceEffortMinutes')::integer) into budget from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text and r->>'locationCodeSnapshot'=code;\n   select sum((r#>>'{work_snapshot,serviceEffortMinutes}')::integer) into actual_effort from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text and r#>>'{work_snapshot,locationCodeSnapshot}'=code;\n   if actual_effort is distinct from budget then raise exception 'Manual native combined group workload budget changed';end if;\n  end loop;\n  if not day_changed and (select count(*) from jsonb_array_elements(p_envelope->'assignments') r where r->>'service_date'=day::text)\n   <>(select count(*) from jsonb_array_elements(source#>'{version,assignments}') r where r->>'dayOfWeek'=dow::text)\n  then raise exception 'Manual native omitted approved normal rows';end if;\n  if day_changed then\n   perform public.static_weekly_manual_assert_absence_score(day_basis,normal_day,policy,expected_availability,p_envelope->'assignments',basis->'ownerConfig');\n  end if;\n end loop;\n if (select count(*) from jsonb_object_keys(links))<>jsonb_array_length(p_envelope->'assignments')\n  or exists(select 1 from jsonb_array_elements(a->'parentLinks') l where not exists(select 1 from jsonb_array_elements(p_envelope->'assignments') r where r->'work_id'=l->'workId' and r->'service_date'=l->'serviceDate'))\n then raise exception 'Manual native foreign row or unused parent link';end if;\n if summary is distinct from public.static_weekly_accepted_exception_set(publication,frame)\n then raise exception 'Manual native original fact did not become exact accepted authority';end if;\n perform public.static_weekly_manual_assert_native_lunch(NULL,p_lunch,p_envelope,publication,frame);\n return jsonb_build_object('assignment_links',links,'projection_assignments',p_envelope->'assignments','kind','INITIAL_EMPLOYMENT_OPERATIONALIZATION');\nend $function$\n","replacement_sha256":"f7269a9b2a5f36901868e04e0792b94ff1f7316ec6476ed6f175f96e5375033a","metadata":{"owner":"postgres","acl":"{postgres=X/postgres}","definer":false,"volatility":"v","strict":false,"config":["search_path=pg_catalog, public"],"parallel":"u","language":"plpgsql"},"inventory":[]}]$targets$::jsonb;
 helpers jsonb:=$helpers$[{"identity":"public.static_weekly_digest_jsonb(jsonb)","sha256":"d79f3cd98da6d3d2d32c979d371488d28632a55d7f8bf85643bb042c54960711"},{"identity":"public.static_weekly_digest_text(text)","sha256":"5337ef6187e2febb0668f1350092fa49de3258317ae19537317a889900a0e1c3"}]$helpers$::jsonb;
 t jsonb;h jsonb;identity text;original text;before_meta jsonb;after_meta jsonb;found_inventory jsonb;expected_inventory jsonb;before_surface jsonb;changed_count integer;observed_crypto jsonb;expected_crypto jsonb:=$crypto${"extname":"pgcrypto","extversion":"1.3","extension_schema":"extensions","server_encoding":"UTF8","function_identity":"digest(bytea,text)","definition":"CREATE OR REPLACE FUNCTION extensions.digest(bytea, text)\n RETURNS bytea\n LANGUAGE c\n IMMUTABLE PARALLEL SAFE STRICT\nAS '$libdir/pgcrypto', $function$pg_digest$function$\n","owner":"postgres","proacl":"{=X/postgres,postgres=X*/postgres,dashboard_user=X/postgres}","prosecdef":false,"provolatile":"i","proisstrict":true,"proparallel":"s","proconfig":null,"lanname":"c","schema_acl":"{postgres=UC/postgres,anon=U/postgres,authenticated=U/postgres,service_role=U/postgres,dashboard_user=UC/postgres}","control_plane_schema_usage":false,"control_plane_execute":true}$crypto$::jsonb;
begin
 select jsonb_build_object('extname',e.extname,'extversion',e.extversion,'extension_schema',n.nspname,
 'server_encoding',current_setting('server_encoding'),'function_identity','digest(bytea,text)',
 'definition',pg_get_functiondef(f.oid),'owner',f.proowner::regrole::text,'proacl',f.proacl::text,
 'prosecdef',f.prosecdef,'provolatile',f.provolatile,'proisstrict',f.proisstrict,'proparallel',f.proparallel,
 'proconfig',to_jsonb(f.proconfig),'lanname',l.lanname,'schema_acl',n.nspacl::text,
 'control_plane_schema_usage',has_schema_privilege('static_weekly_control_plane',n.oid,'USAGE'),
 'control_plane_execute',has_function_privilege('static_weekly_control_plane',f.oid,'EXECUTE'))
 into strict observed_crypto from pg_extension e join pg_namespace n on n.oid=e.extnamespace
 join pg_proc f on f.oid=to_regprocedure('extensions.digest(bytea,text)') join pg_language l on l.oid=f.prolang
 where e.extname='pgcrypto' and f.pronamespace=n.oid and exists(select 1 from pg_depend dep
  where dep.classid='pg_proc'::regclass and dep.objid=f.oid and dep.refclassid='pg_extension'::regclass
   and dep.refobjid=e.oid and dep.deptype='e');
 if observed_crypto is distinct from expected_crypto then raise exception 'Exact existing pgcrypto binding differs';end if;
 for h in select value from jsonb_array_elements(helpers) loop
  if public.static_weekly_digest_text(pg_get_functiondef(to_regprocedure(h->>'identity'))) is distinct from h->>'sha256' then
   raise exception 'Exact unchanged digest helper differs: %',h->>'identity';end if;
 end loop;
 if not exists(select 1 from pg_trigger where tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  and tgname='trg_custodial_release_authority_restore_inventory_immutable' and tgenabled='A') then
  raise exception 'Digest repair recovery guard is not ALWAYS';end if;
 select coalesce(jsonb_agg(to_jsonb(s) order by object_kind,object_identity),'[]'::jsonb) into before_surface
  from public.custodial_release_canary_authority_surface() s;
 -- Validate every predecessor before the first change.
 for t in select value from jsonb_array_elements(targets) loop
  identity:=t->>'identity';original:=pg_get_functiondef(to_regprocedure(identity));
  if public.static_weekly_digest_text(original) is distinct from t->>'preimage_sha256' then
   raise exception 'Exact digest caller predecessor differs: %',identity;end if;
  select jsonb_build_object('owner',proowner::regrole::text,'acl',proacl::text,'definer',prosecdef,
   'volatility',provolatile,'strict',proisstrict,'config',to_jsonb(proconfig),'parallel',proparallel,'language',l.lanname)
   into strict before_meta from pg_proc f join pg_language l on l.oid=f.prolang where f.oid=to_regprocedure(identity);
  if before_meta is distinct from t->'metadata' then raise exception 'Exact digest caller metadata differs: %',identity;end if;
  select coalesce(jsonb_agg(jsonb_build_object('object_kind',object_kind,'object_identity',object_identity,'restore_order',restore_order,
   'definition_sql',definition_sql,'definition_sha256',definition_sha256) order by object_kind,object_identity,restore_order),'[]'::jsonb)
   into found_inventory from public.custodial_release_authority_restore_inventory
   where object_identity in(identity,replace(identity,'public.',''));
  if found_inventory is distinct from t->'inventory' then raise exception 'Exact digest caller recovery predecessor differs: %',identity;end if;
  if public.static_weekly_digest_text(t->>'replacement') is distinct from t->>'replacement_sha256' then
   raise exception 'Digest caller replacement identity differs: %',identity;end if;
 end loop;
 for t in select value from jsonb_array_elements(targets) loop
  identity:=t->>'identity';execute t->>'replacement';
  select jsonb_build_object('owner',proowner::regrole::text,'acl',proacl::text,'definer',prosecdef,
   'volatility',provolatile,'strict',proisstrict,'config',to_jsonb(proconfig),'parallel',proparallel,'language',l.lanname)
   into strict after_meta from pg_proc f join pg_language l on l.oid=f.prolang where f.oid=to_regprocedure(identity);
  if pg_get_functiondef(to_regprocedure(identity)) is distinct from t->>'replacement' or after_meta is distinct from t->'metadata' then
   raise exception 'Digest caller replacement authority/readback differs: %',identity;end if;
 end loop;
 alter table public.custodial_release_authority_restore_inventory disable trigger trg_custodial_release_authority_restore_inventory_immutable;
 for t in select value from jsonb_array_elements(targets) loop
  identity:=t->>'identity';
  update public.custodial_release_authority_restore_inventory set definition_sql=t->>'replacement',
   definition_sha256=t->>'replacement_sha256',captured_at=statement_timestamp()
   where object_kind='function' and object_identity in(identity,replace(identity,'public.',''))
    and definition_sha256=t->>'preimage_sha256';
  get diagnostics changed_count=row_count;
  if changed_count<>(select count(*) from jsonb_array_elements(t->'inventory') r where r->>'object_kind'='function') then
   raise exception 'Digest caller exact recovery update count differs: %',identity;end if;
 end loop;
 alter table public.custodial_release_authority_restore_inventory enable always trigger trg_custodial_release_authority_restore_inventory_immutable;
 for t in select value from jsonb_array_elements(targets) loop
  identity:=t->>'identity';
  select coalesce(jsonb_agg(case when r->>'object_kind'='function' then r||jsonb_build_object('definition_sql',t->>'replacement',
   'definition_sha256',t->>'replacement_sha256') else r end order by r->>'object_kind',r->>'object_identity',(r->>'restore_order')::integer),'[]'::jsonb)
   into expected_inventory from jsonb_array_elements(t->'inventory') r;
  select coalesce(jsonb_agg(jsonb_build_object('object_kind',object_kind,'object_identity',object_identity,'restore_order',restore_order,
   'definition_sql',definition_sql,'definition_sha256',definition_sha256) order by object_kind,object_identity,restore_order),'[]'::jsonb)
   into found_inventory from public.custodial_release_authority_restore_inventory
   where object_identity in(identity,replace(identity,'public.',''));
  if found_inventory is distinct from expected_inventory then raise exception 'Digest caller recovery/grant readback differs: %',identity;end if;
 end loop;
 if before_surface is distinct from (select coalesce(jsonb_agg(to_jsonb(s) order by object_kind,object_identity),'[]'::jsonb)
  from public.custodial_release_canary_authority_surface() s) then raise exception 'Digest repair changed authority surface';end if;
 for h in select value from jsonb_array_elements(helpers) loop
  if public.static_weekly_digest_text(pg_get_functiondef(to_regprocedure(h->>'identity'))) is distinct from h->>'sha256' then
   raise exception 'Digest repair changed global helper';end if;
 end loop;
 if not exists(select 1 from pg_trigger where tgrelid='public.custodial_release_authority_restore_inventory'::regclass
  and tgname='trg_custodial_release_authority_restore_inventory_immutable' and tgenabled='A') then
  raise exception 'Digest repair did not preserve ALWAYS guard';end if;
select jsonb_build_object('extname',e.extname,'extversion',e.extversion,'extension_schema',n.nspname,
 'server_encoding',current_setting('server_encoding'),'function_identity','digest(bytea,text)',
 'definition',pg_get_functiondef(f.oid),'owner',f.proowner::regrole::text,'proacl',f.proacl::text,
 'prosecdef',f.prosecdef,'provolatile',f.provolatile,'proisstrict',f.proisstrict,'proparallel',f.proparallel,
 'proconfig',to_jsonb(f.proconfig),'lanname',l.lanname,'schema_acl',n.nspacl::text,
 'control_plane_schema_usage',has_schema_privilege('static_weekly_control_plane',n.oid,'USAGE'),
 'control_plane_execute',has_function_privilege('static_weekly_control_plane',f.oid,'EXECUTE'))
 into strict observed_crypto from pg_extension e join pg_namespace n on n.oid=e.extnamespace
 join pg_proc f on f.oid=to_regprocedure('extensions.digest(bytea,text)') join pg_language l on l.oid=f.prolang
 where e.extname='pgcrypto' and f.pronamespace=n.oid and exists(select 1 from pg_depend dep
  where dep.classid='pg_proc'::regclass and dep.objid=f.oid and dep.refclassid='pg_extension'::regclass
   and dep.refobjid=e.oid and dep.deptype='e');
 if observed_crypto is distinct from expected_crypto then raise exception 'Exact existing pgcrypto binding differs';end if;
end $digest_callsite$;
commit;
